import React, { useState, useMemo, useRef, useEffect, useContext } from 'react';
import { Switch, Route, Redirect, useHistory } from 'react-router-dom';
import { Layout, Menu, Breadcrumb, Spin, Skeleton, ConfigProvider, Modal, Form, Input } from '@arco-design/web-react';
import {
  IconCommon,
  IconCopyright,
  IconDriveFile, IconLanguage, IconMenu, IconSave,
} from '@arco-design/web-react/icon';
import { observer } from 'mobx-react-lite';
import store from '@/store';
import qs from 'query-string';
import NProgress from 'nprogress';
import useRoute, { mainRoutes } from '@/routes';
import { isArray } from '../utils/is';
import lazyload from '../utils/lazyload';
import styles from './layout.module.less';
import { toJS } from 'mobx';
import { IRoute } from '../types/route';
import zhCN from '@arco-design/web-react/es/locale/zh-CN';
import { DndProvider } from 'react-dnd';
import { HTML5Backend } from 'react-dnd-html5-backend';
import checkLogin from '@/utils/checkLogin';
import { returnToLogin } from '@/utils';
import ajax from '@/utils/ajax';
import useLocale from '@/utils/useLocale';
import MainHeader from './components/MainHeader';
import { beforLogin } from './login';
import userStore from '@/store/userStore';
const { Header, Content } = Layout;

const MenuItem = Menu.Item;
const SubMenu = Menu.SubMenu;


function getIconFromKey(key) {
    switch (key) {
      case 'system/page':
      case 'system/pages':
        return <IconDriveFile className={styles.icon} />;
      case 'system/module':
        return <IconCommon className={styles.icon} />
      case 'system/menu':
        return <IconMenu className={styles.icon} />;
      case 'system/multilingual':
        return <IconLanguage />;
      case 'system/version':
        return <IconSave />;
    }
}
  
  function getFlattenRoutes(routes) {
    const mod = import.meta.glob('../pages/**/[a-z[]*.tsx');
    const res = [];
    function travel(_routes) {
      _routes.forEach((route) => {
        if (isArray(route.children) && route.children.length) {
          travel(route.children);
        }
        route.component = lazyload(mod[`../pages/${route.path || route.key}/index.tsx`]);
        res.push(route);
      });
    }
    travel(toJS(routes));
    return res;
}

interface PageLayoutProps {
  notLogin?: boolean;
}

function PageLayout({
  notLogin = false,
}: PageLayoutProps) {
  const history = useHistory();
  const pathname = history.location.pathname;
  const locale = useLocale();
  const currentComponent = qs.parseUrl(pathname).url.slice(1);

  useState(() => {
    import('./init');
  })


  const [routes, defaultRoute] = useRoute(userStore.permissions, mainRoutes);
  const paths = (currentComponent || defaultRoute).split('/');
  const defaultSelectedKeys = [currentComponent || defaultRoute];
  const [selectedKeys, setSelectedKeys] = useState<string[]>(defaultSelectedKeys);
  const defaultOpenKeys = paths.slice(0, paths.length - 1);

  const [openKeys, setOpenKeys] = useState<string[]>(defaultOpenKeys);

  const routeMap = useRef<Map<string, React.ReactNode[]>>(new Map());
  const menuMap = useRef<
    Map<string, { menuItem?: boolean; subMenu?: boolean }>
  >(new Map());

  function renderRoutes(locale) {
    routeMap.current.clear();
    return function travel(_routes: IRoute[], level, parentNode = []) {

      return _routes.map((route) => {
        const { breadcrumb = true, ignore } = route;
        const iconDom = getIconFromKey(route.icon || route.key);
        const titleDom = (
          <>
            {iconDom} {locale[route.name] || route.name}
          </>
        );

        routeMap.current.set(
          `/${route.key}`,
          breadcrumb ? [...parentNode, route.name] : []
        );

        const visibleChildren = (route.children || []).filter((child) => {
          const { ignore, breadcrumb = true } = child;
          if (ignore || route.ignore) {
            routeMap.current.set(
              `/${child.key}`,
              breadcrumb ? [...parentNode, route.name, child.name] : []
            );
          }

          return !ignore;
        });

        if (ignore) {
          return '';
        }
        if (visibleChildren.length) {
          menuMap.current.set(route.key, { subMenu: true });
          // console.log('titleDom', titleDom, route)
          return (
            <SubMenu key={route.key} title={titleDom}>
              {travel(visibleChildren, level + 1, [...parentNode, route.name])}
            </SubMenu>
          );
        }
        menuMap.current.set(route.key, { menuItem: true });
        return <MenuItem key={route.key}>{titleDom}</MenuItem>;
      });
    };
  }


  const flattenRoutes = useMemo(() => getFlattenRoutes(routes) || [], [routes]);


  function updateMenuStatus() {
    const pathKeys = pathname.split('/');
    const newSelectedKeys: string[] = [];
    const newOpenKeys: string[] = [...openKeys];
    while (pathKeys.length > 0) {
      const currentRouteKey = pathKeys.join('/');
      const menuKey = currentRouteKey.replace(/^\//, '');
      const menuType = menuMap.current.get(menuKey);
      // console.log('menuMap', menuKey, menuMap)
      if (menuType && menuType.menuItem) {
        newSelectedKeys.push(menuKey);
      }
      if (menuType && menuType.subMenu && !openKeys.includes(menuKey)) {
        newOpenKeys.push(menuKey);
      }
      pathKeys.pop();
    }
    setOpenKeys(newOpenKeys);
  }

  function onClickMenuItem(key) {
    const currentRoute = flattenRoutes.find((r) => r.key === key);
    setSelectedKeys([key]);
    const component = currentRoute.component;
    // console.log('onClickMenuItem', currentRoute, key)
    if(!component.preload){
      // 同步组件，不需要异步加载
      history.push(`/${key}`);
      return;
    }
    const preload = component.preload();
    NProgress.start();
    preload.then(() => {
      // history.push(`/${currentRoute.path || key}`);
      NProgress.done();
    });
    history.push(`/${currentRoute.path || key}`);
  }


  useEffect(() => {
    updateMenuStatus();
  }, [routes]);


  const componentConfig = useMemo(() => {
    return {
      Card: {
        bordered: false,
      },
      List: {
        bordered: false,
      },
      Modal: {
        maskClosable: false,
        escToExit: false,
      },
      Table: {
        border: false,
      },
    }
  },[])

  const menuChildren = useMemo(() => {
    return renderRoutes(locale)(routes, 1);
  },[routes])

  const routeChildren = useMemo(() => {
    return flattenRoutes.map((route, index) => {
      return (
        <Route
          key={index}
          path={`/${route.key}`}
          component={route.component}
        />
      );
    })
  },[flattenRoutes])

  return (
    <ConfigProvider
      locale={zhCN}
      componentConfig={componentConfig}
    >
    <DndProvider backend={HTML5Backend}>
    {userStore.userLoading? (
      <Layout className={styles.layout}>
        <Header>
          <MainHeader>
            <Menu
              mode="horizontal"
              onClickMenuItem={onClickMenuItem}
              selectedKeys={selectedKeys}
              openKeys={openKeys}
              onClickSubMenu={(_, openKeys) => {
                setOpenKeys(openKeys);
              }}
            >
              {menuChildren}
            </Menu>
          </MainHeader>
        </Header>
        <Content className={styles.Content}>
          <Switch>
              {routeChildren}
              <Route exact path="/">
                <Redirect to={`/${defaultRoute}`} />
              </Route>
              {!flattenRoutes.length? <Spin /> : (
                <Route
                    path="*"
                    component={lazyload(() => import('@/pages/exception/403'))}
                />
              )}
          </Switch>
        </Content>
      </Layout>
    ): (
      <div className={styles.spin}>Loading...</div>
      // <Skeleton animation text={{ rows: 20 }}></Skeleton>
    )}
    </DndProvider>
    </ConfigProvider>
  );
}

export default beforLogin(observer(PageLayout));
