import {
  PageHeader, Message, Radio, Menu,
  Tooltip, Image, Dropdown, Avatar, Divider, Space,
  Button
} from '@arco-design/web-react';
import { HTMLProps, ReactNode } from 'react';
import styles from './style.module.less';
import app from '@/store/app';
import { IconDashboard, IconExperiment, IconMoonFill, IconPoweroff, IconSettings, IconSunFill, IconTag, IconUser } from '@arco-design/web-react/icon';
import useLocale from '@/utils/useLocale';
import userStore from '@/store/userStore';
import { useObserver } from 'mobx-react-lite';

interface LayoutHeaderProps extends HTMLProps<HTMLDivElement> {
  logo?: string;
  title?: string;
}
const LayoutHeader = (props: LayoutHeaderProps) => {
  const t = useLocale();


  function onMenuItemClick(key) {
    if (key === 'logout') {
      // 退出登陆
      userStore.logout();
    } else {
      Message.info(`You clicked ${key}`);
    }
  }


  const droplist = (
    <Menu onClickMenuItem={onMenuItemClick}>
      <Menu.Item key="logout">
        <IconPoweroff className={styles['dropdown-icon']} />
        {t['navbar.logout']}
      </Menu.Item>
    </Menu>
  );
  

  return useObserver(() => {

    return (
      <div className={styles.component}>
        <div className={styles.topHeader}>
          <img className={styles.logoImg} src={'/imgs/logo.svg'} />
          {/* <div className={styles.topTitle}>
            模版产品管理中心
          </div> */}
          <div className={styles.layoutMenu}>
            {props.children}
          </div>
          <Space>
            <Tooltip
              content={
                app.theme == 'dark'
                  ? t['settings.navbar.theme.toDark']
                  : t['settings.navbar.theme.toLight']
              }
            >
              <Button
                shape="round"
                icon={app.theme !== 'dark' ? <IconMoonFill /> : <IconSunFill />}
                onClick={() => app.setTheme(app.theme !== 'dark' ? 'dark' : 'light')}
              />
            </Tooltip>
            {userStore.user && (
              <Dropdown droplist={droplist} position="br">
                <Avatar size={28} style={{ cursor: 'pointer' }}>
                  {/* <img alt="avatar" src={userStore.user.avatar} /> */}
                  <IconUser />
                </Avatar>
                <span>{userStore.user.id}</span>
              </Dropdown>
            )}
          </Space>
        </div>
      </div>
    );

  })

};

export default LayoutHeader;

